function read(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return v===null?fallback:v}catch{return fallback}}
function normalizeSaved(book){if(!book||!book.id||!book.title)return null;let image=book.image||null;if(!image&&book.yes24Id)image='https://image.yes24.com/goods/'+book.yes24Id+'/L';if(!image&&book.coverId)image='https://covers.openlibrary.org/b/id/'+book.coverId+'-L.jpg';const description=book.source==='example'&&SEED_HOOKS[book.id]?SEED_HOOKS[book.id]:book.description;return {...book,author:book.author||'저자 정보 없음',image,description,tags:Array.isArray(book.tags)?book.tags:[],goals:Array.isArray(book.goals)?book.goals:[],board:BOARD_NAMES[book.board]?book.board:'want'} }
function normalizeUpNext(ids,saved){if(!Array.isArray(ids))return [];const eligible=new Set(saved.filter((book)=>book.board==='want').map((book)=>book.id));return [...new Set(ids.filter((id)=>typeof id==='string'&&eligible.has(id)))].slice(0,3)}
function normalizeCollections(list,saved){if(!Array.isArray(list))return [];const bookIds=new Set(saved.map((book)=>book.id));return list.filter((entry)=>entry&&typeof entry.id==='string'&&typeof entry.name==='string'&&entry.name.trim()).slice(0,20).map((entry)=>({id:entry.id,name:entry.name.trim().slice(0,36),books:[...new Set((Array.isArray(entry.books)?entry.books:[]).filter((id)=>bookIds.has(id)))],extras:[...new Set((Array.isArray(entry.extras)?entry.extras:[]).filter((id)=>typeof id==='string'))]}))}
function normalizeShelfDecor(value){const wall=value?.wall==='linen'?'linen':'plain';const valid=new Set(SHELF_DECOR_OBJECTS.map((item)=>item.id));const previous=Array.isArray(value?.objects)?value.objects:[value?.object];const objects=[...new Set(previous.filter((id)=>valid.has(id)))];return {wall,objects,inspiredBy:typeof value?.inspiredBy==='string'?value.inspiredBy:''}}
