function replaceState(data){const fresh=blankState();if(data&&typeof data==='object'){const p=data.profile||{};fresh.profile={interests:Array.isArray(p.interests)?p.interests.filter((x)=>INTERESTS.includes(x)):[],goals:Array.isArray(p.goals)?p.goals.filter((x)=>GOALS.includes(x)):[],vibes:Array.isArray(p.vibes)?p.vibes.filter((x)=>VIBES.includes(x)):[],careerFocus:Array.isArray(p.careerFocus)&&Array.isArray(p.interests)&&p.interests.includes('일과 커리어')?p.careerFocus.filter((x)=>CAREER_FOCUS.includes(x)):[],length:['any','short','long'].includes(p.length)?p.length:'any',favorite:typeof p.favorite==='string'?p.favorite.slice(0,80):''};fresh.saved=Array.isArray(data.saved)?data.saved.map(normalizeSaved).filter(Boolean):[];fresh.upNext=normalizeUpNext(data.upNext,fresh.saved);fresh.collections=normalizeCollections(data.collections,fresh.saved);fresh.ignored=Array.isArray(data.ignored)?data.ignored.filter((x)=>typeof x==='string'):[];fresh.shelfDecor=normalizeShelfDecor(data.shelfDecor)}Object.assign(state,fresh);shelfPreview=false;quickActive=!!(state.profile.interests.length&&state.profile.goals.length);quickLoading=quickActive;currentBoard='want';currentFilter='all';currentQuery='';$('searchInput').value='';renderProfile();renderBoards();renderShortlist();loadBooks('')}
function setAccountSaveHandler(handler){accountSaveHandler=handler}
