function normalizeGoogle(item){const v=item.volumeInfo||{};return {id:'google:'+item.id,title:v.title||'',author:(v.authors||[]).join(', ')||'저자 정보 없음',description:v.description||'',tags:v.categories||[],goals:[],pages:v.pageCount||null,image:(v.imageLinks&& (v.imageLinks.thumbnail||v.imageLinks.smallThumbnail)||'').replace(/^http:/,'https:'),url:(v.infoLink||'https://books.google.com/').replace(/^http:/,'https:'),source:'google'}}
function normalizeOpen(item){return {id:'open:'+item.key,title:item.title||'',author:(item.author_name||[]).slice(0,2).join(', ')||'저자 정보 없음',description:'',tags:(item.subject||[]).slice(0,8),goals:[],pages:item.number_of_pages_median||null,image:item.cover_i?'https://covers.openlibrary.org/b/id/'+item.cover_i+'-L.jpg?default=false':null,url:'https://openlibrary.org'+item.key,source:'openlibrary'}}
async function fetchJson(url,timeout=6000){const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),timeout);try{const response=await fetch(url,{signal:ctl.signal});if(!response.ok)throw Error('HTTP '+response.status);return await response.json()}finally{clearTimeout(timer)}}
function domesticQuery(query){if(query)return query;const p=state.profile;if(p.interests.includes('일과 커리어')&&p.careerFocus.length)return KOREAN_CAREER_SEARCH[p.careerFocus[0]];if(p.interests.length)return KOREAN_INTEREST_SEARCH[p.interests[0]];if(p.favorite.trim())return p.favorite.trim();return '책'}
async function searchKoreanBooks(query,page){try{const base=location.port==='8765'&&/^(localhost|127\.0\.0\.\d+)$/.test(location.hostname)?'http://localhost:8767':'';const data=await fetchJson(base+'/api/books?query='+encodeURIComponent(query)+'&page='+page,9000);kakaoConfigured=!!data.configured;if(!data.configured)return {books:[],source:'kakao'};const interest=state.profile.interests[0]||'';return {books:(data.books||[]).map((book)=>({...book,searchInterest:interest})),source:'kakao'}}catch(error){kakaoConfigured=/HTTP 429/.test(error.message)?'quota':false;console.info('Kakao Books unavailable:',error.message);return {books:[],source:'kakao'}}}
async function searchRemote(query,page=1){const q=encodeURIComponent(query);let googleBooks=[];if(Date.now()>=googleBlockedUntil){try{const data=await fetchJson('https://www.googleapis.com/books/v1/volumes?q='+q+'&printType=books&maxResults=40&startIndex='+(page-1)*40);googleBooks=(data.items||[]).map(normalizeGoogle).filter((b)=>b.title);if(googleBooks.length>=15)return {books:googleBooks,source:'google'}}catch(e){if(/HTTP 429/.test(e.message))googleBlockedUntil=Date.now()+10*60*1000;console.info('Google Books unavailable:',e.message)}}try{const language=/[가-힣]/.test(query)?'ko':'en';const term=query.toLowerCase()==='fiction'?'subject=fiction':'q='+q;const data=await fetchJson('https://openlibrary.org/search.json?'+term+'&lang='+language+'&limit=40&page='+page+'&fields=key,title,author_name,cover_i,number_of_pages_median,subject');const openBooks=(data.docs||[]).map(normalizeOpen).filter((b)=>b.title);if(openBooks.length&&googleBooks.length)return {books:uniqueBooks([...googleBooks,...openBooks]),source:'mixed'};if(openBooks.length)return {books:openBooks,source:'openlibrary'}}catch(e){console.info('Open Library unavailable:',e.message)}return {books:googleBooks,source:googleBooks.length?'google':'example'}}
function candidateQuery(){const p=state.profile;if(p.interests.includes('일과 커리어')&&p.careerFocus.length)return CAREER_SEARCH[p.careerFocus[0]];const keywords={'소설':'fiction','일과 커리어':'career development business','마음과 관계':'psychology','인문·사회':'social science','과학':'science','여행':'travel','경제':'finance'};if(p.interests.length&&p.vibes.length)return (keywords[p.interests[0]]||p.interests[0])+' '+VIBE_SEARCH[p.vibes[0]];if(p.interests.length)return keywords[p.interests[0]]||p.interests[0];if(p.vibes.length)return VIBE_SEARCH[p.vibes[0]];if(p.favorite.trim())return p.favorite.trim();if(state.saved.length)return state.saved[0].author;if(p.goals.includes('실무에 적용'))return 'business';if(p.goals.includes('새로운 관점'))return 'ideas';return 'books'}
function candidateQueries(){const first=candidateQuery(),p=state.profile;const keywords={'소설':'fiction','일과 커리어':'career development business','마음과 관계':'psychology','인문·사회':'social science','과학':'science','여행':'travel','경제':'finance'};const extra=p.favorite.trim()&&p.favorite.trim()!==first?p.favorite.trim():p.careerFocus.length>1?CAREER_SEARCH[p.careerFocus[1]]:p.interests.length>1?keywords[p.interests[1]]||p.interests[1]:'';return [...new Set([first,extra].filter(Boolean))].slice(0,2)}
async function loadBooks(query,page=1){const serial=++requestSerial;currentQuery=query||'';quickLoading=quickActive&&!currentQuery;renderShortlist();if(!currentQuery&&!anySignal()&&page===1){currentBooks=SEEDS.slice();currentSource='curated';currentPage=0;quickLoading=false;renderShortlist();renderFeed();return}$('feedStatus').textContent='책을 찾고 있습니다…';const queries=currentQuery?[currentQuery]:candidateQueries(),results=await Promise.all([searchKoreanBooks(domesticQuery(currentQuery),page),...queries.map((term)=>searchRemote(term,page))]);if(serial!==requestSerial)return;const external=uniqueBooks(results.flatMap((result)=>result.books)),sources=new Set(results.filter((result)=>result.books.length).map((result)=>result.source));const examples=currentQuery?SEEDS.filter((b)=>(b.title+' '+b.author+' '+b.tags.join(' ')).toLowerCase().includes(currentQuery.toLowerCase())):SEEDS.slice();if(external.length){currentBooks=currentQuery?refineSearch(external,currentQuery):external;currentSource=sources.size>1?'mixed':[...sources][0]}else if(page>1&&!currentQuery){discoveryRound=page-2;quickLoading=false;renderShortlist();renderFeed();$('feedStatus').textContent='다른 책을 불러오지 못했습니다. 잠시 뒤 다시 시도해 주세요.';return}else{currentBooks=examples;currentSource='example'}currentPage=0;quickLoading=false;renderShortlist();renderFeed()}
function save(book,board){if(savedBook(book.id)){const item=savedBook(book.id),wasDone=item.board==='done';item.board=board||item.board;if(item.board==='done'&&!wasDone)item.finishedAt=Date.now();if(item.board!=='want')state.upNext=state.upNext.filter((id)=>id!==book.id);toast('보드를 변경했습니다.')}else{const nextBoard=board||'want';state.saved.push({...book,board:nextBoard,...(nextBoard==='done'?{finishedAt:Date.now()}:{})});toast(nextBoard==='done'?'다 읽은 책에 저장했습니다.':'읽고 싶어요 보드에 저장했습니다.')}shelfPreview=false;persist();renderFeed();renderBoards();renderShortlist()}
function remove(id){state.saved=state.saved.filter((b)=>b.id!==id);state.upNext=state.upNext.filter((nextId)=>nextId!==id);for(const entry of state.collections)entry.books=entry.books.filter((bookId)=>bookId!==id);persist();renderFeed();renderBoards();renderShortlist();toast('보드에서 삭제했습니다.')}
function related(book){if(!book.author||book.author==='저자 정보 없음')return [];return uniqueBooks([...currentBooks,...SEEDS,...state.saved]).filter((other)=>other.id!==book.id&&!savedBook(other.id)&&!state.ignored.includes(other.id)&&other.author===book.author).slice(0,4)}
function findBook(id){return [...state.saved,...currentBooks,...SEEDS].find((b)=>b.id===id)}
async function enrichOpenBook(book){
  if(book.source!=='openlibrary'||book.description||workDetailsCache.has(book.id))return;
  const key=book.id.slice(5);if(!/^\/works\/OL\d+W$/.test(key))return;
  workDetailsCache.set(book.id,null);
  try{const data=await fetchJson('https://openlibrary.org'+key+'.json');const raw=typeof data.description==='string'?data.description:data.description?.value||data.first_sentence?.value||data.first_sentence||'';const description=String(raw).replace(/<[^>]+>/g,'').trim().slice(0,650);if(description){book.description=description;const saved=savedBook(book.id);if(saved){saved.description=description;persist()}workDetailsCache.set(book.id,description)}}catch(error){console.info('Open Library work details unavailable:',error.message)}
  if($('bookDialog').open&&$('bookDialog').dataset.bookId===book.id)openBook(book.id)
}
