  $('dialogBody').innerHTML='<div class="dialog-layout"><div>'+cover(book).replace('<span class="cover-placeholder"','<span class="cover-placeholder dialog-cover"').replace('<img ','<img class="dialog-cover" ')+'</div><div class="dialog-copy"><span class="eyebrow">'+clean(({kakao:'카카오 책 검색',google:'GOOGLE BOOKS',openlibrary:'OPEN LIBRARY',example:'FOLIO EDITORIAL PICK'}[book.source]||'SAVED BOOK'))+'</span><h2>'+clean(book.title)+'</h2><p>'+clean(book.author)+(book.pages?' · 약 '+book.pages+'쪽':'')+'</p><p class="description">'+clean(plainBookText(description))+'</p>'+(showEvidence?recommendationMarkup(book):'')+'<div class="dialog-actions">'+Object.keys(BOARD_NAMES).map((key)=>'<button type="button" data-move="'+clean(book.id)+'" data-to="'+key+'" class="'+(current&&current.board===key?'active':'')+'">'+BOARD_NAMES[key]+'</button>').join('')+(current&&current.board==='want'?'<button type="button" data-next="'+clean(book.id)+'" class="'+(state.upNext.includes(book.id)?'active':'')+'">'+(state.upNext.includes(book.id)?'다음에 읽기 해제':'다음에 읽기 +')+'</button>':'')+(current?'<button type="button" data-remove="'+clean(book.id)+'">보드에서 삭제</button>':'<button type="button" data-ignore="'+clean(book.id)+'">관심 없음</button>')+'<a href="'+clean(safeUrl(book.url))+'" target="_blank" rel="noopener noreferrer">책 정보 보기 ↗</a></div>'+collectionPicker('book',book.id)+(current?'<label class="field-label" for="bookNote">나만의 한 줄</label><textarea id="bookNote" data-note="'+clean(book.id)+'" maxlength="500" placeholder="읽고 싶은 이유나 기억할 문장을 적어보세요">'+clean(current.note||'')+'</textarea>':'')+'<p class="related-head">같은 작가의 다른 책</p><div class="related-list">'+(relatedBooks.length?relatedBooks.map((b)=>'<button type="button" data-open="'+clean(b.id)+'">'+clean(b.title)+'<br><small>'+clean(b.author)+'</small></button>').join(''):'<span>현재 목록에는 같은 작가의 다른 책이 없습니다.</span>')+'</div></div></div>';
  if(!$('bookDialog').open)$('bookDialog').showModal();
